        _lang() {
            // v1.2: the live language is window.vcI18n._lang (Lessons_Learned_USF_i18n_and_Modals.md, 2026-08-20).
            // The framework has no .language or .currentLanguage; those reads stay only as fallbacks.
            var raw = '';
            try { if (window.vcI18n && window.vcI18n._lang) { raw = window.vcI18n._lang; } } catch (e) {}
            var sim = window.mySimulation;
            if (!raw) { raw = (sim && sim.language) || (sim && sim.currentLanguage) || document.documentElement.lang || 'en'; }
            return (raw && raw.toString().toLowerCase().indexOf('es') === 0) ? 'es' : 'en';
        }

        _t(obj) {
            var l = this._lang();
            return (obj && obj[l]) ? obj[l] : (obj ? obj['en'] || '' : '');
        }

        _L(en, es) { return this._lang() === 'es' ? es : en; }

        _num(v) {
            var r = Math.round(v * 100) / 100;
            try { return r.toLocaleString(this._lang() === 'es' ? 'es-ES' : 'en-US'); } catch (e) { return String(r); }
        }

        _freshDomain() {
            return {
                totalScore: 0,
                scenariosCompleted: 0,
                scoreHistory: [],
                efficiencyHistory: [],
                objectiveHistory: [],
                optimalHistory: [],
                planHistory: [],
                readHistory: [],
                feasibleHistory: [],
                decisionHistory: [],
                lastShown: 0
            };
        }

        initialize(state) {
            // Reset on a fresh start or whenever no completed round remains (undo to the start).
            if (!state.domainState || Object.keys(state.domainState).length === 0 || !state.history || state.history.length === 0) {
                state.domainState = this._freshDomain();
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = { var1: 0, var2: 0, var3: 0, relax: '' };
            }
            this._bindLanguage();
            this._updateBriefing(state);
        }

        _bindLanguage() {
            if (this.__langBound) { return; }
            this.__langBound = true;
            var self = this;
            var repaint = function () { try { self._repaint(); } catch (e) {} };
            document.addEventListener('express:langchanged', repaint);
            var tries = 0;
            (function hook() {
                var f = window.mySimulation;
                if (f && f.eventBus && typeof f.eventBus.on === 'function') {
                    f.eventBus.on('language:changed', repaint);
                    // After an undo the round to replay is shown again; the inputs the framework restored are kept.
                    f.eventBus.on('period:undone', function (st) {
                        try {
                            var s2 = st || (window.mySimulation && window.mySimulation.state) || {};
                            self._paintRound(Math.min((s2.currentPeriod || 1) - 1, self.ROUNDS.length - 1), false);
                            var rp = document.getElementById('resultsPanel');
                            if (rp) { rp.style.display = 'none'; }
                        } catch (e) {}
                    });
                    return;
                }
                if (++tries < 50) { setTimeout(hook, 100); }
            })();
        }

        // Repaint every adapter-written text in the current language without touching the inputs.
        _repaint() {
            var f = window.mySimulation;
            var st = f && f.state;
            if (!st) { return; }
            var maxP = st.maxPeriods || this.ROUNDS.length;
            var idx = Math.min((st.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            this._paintRound(idx, false);
            var ds = st.domainState || {};
            var rp = document.getElementById('resultsPanel');
            if (rp && rp.style.display !== 'none' && ds.lastShown && ds.decisionHistory && ds.decisionHistory[ds.lastShown - 1]) {
                var rec = ds.decisionHistory[ds.lastShown - 1];
                this._showResults(ds.lastShown - 1, rec.vals, rec.relax);
            }
            if (maxP && (st.currentPeriod || 1) > maxP) { return; }
        }

        _relaxOptions(idx) {
            var round = this.ROUNDS[idx];
            var out = [];
            for (var c = 0; c < round.constraints.length; c++) {
                out.push({ value: 'c' + c, text: this._t(round.shadowPrices[c].name) + ': ' + this._t(round.constraints[c].desc).replace(/\s*\(.*\)\s*$/, '') });
            }
            return out;
        }

        _paintRound(idx, resetInputs) {
            var round = this.ROUNDS[idx];
            var titleEl = document.getElementById('roundTitle');
            if (titleEl) titleEl.innerHTML = this._t(round.title);
            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = this._t(round.briefing);
            var conEl = document.getElementById('constraintList');
            if (conEl) {
                var html = '<strong>' + this._L('Constraints:', 'Restricciones:') + '</strong><br>';
                for (var c = 0; c < round.constraints.length; c++) { html += this._t(round.constraints[c].desc) + '<br>'; }
                conEl.innerHTML = html;
            }
            var objEl = document.getElementById('objectiveDisplay');
            if (objEl) objEl.innerHTML = this._t(round.objDesc);
            for (var v = 0; v < 3; v++) {
                var grp = document.getElementById('var' + (v + 1) + 'Group');
                var lbl = document.getElementById('var' + (v + 1) + 'Label');
                var inp = document.getElementById('var' + (v + 1) + 'Input');
                if (!grp) { continue; }
                if (v < round.activeVars) {
                    grp.style.display = 'block';
                    if (lbl) lbl.textContent = this._t(round.varLabels)[v] || '';
                    if (inp) {
                        inp.min = round.varMins[v];
                        inp.max = round.varMaxs[v];
                        if (resetInputs) inp.value = round.varDefaults[v];
                    }
                } else {
                    grp.style.display = 'none';
                    if (inp && resetInputs) inp.value = 0;
                }
            }
            var sel = document.getElementById('relaxInput');
            if (sel) {
                var opts = this._relaxOptions(idx);
                var same = sel.getAttribute('data-round') === String(idx) && !resetInputs;
                if (same) {
                    for (var o = 0; o < sel.options.length; o++) {
                        for (var k = 0; k < opts.length; k++) { if (sel.options[o].value === opts[k].value) { sel.options[o].text = opts[k].text; } }
                    }
                } else {
                    var keep = resetInputs ? '' : sel.value;
                    var oh = '';
                    for (var q = 0; q < opts.length; q++) { oh += '<option value="' + opts[q].value + '">' + opts[q].text + '</option>'; }
                    sel.innerHTML = oh;
                    sel.setAttribute('data-round', String(idx));
                    sel.value = keep;
                    if (resetInputs) { sel.selectedIndex = -1; }
                }
            }
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            this._paintRound(idx, true);
            var rp = document.getElementById('resultsPanel');
            if (rp) rp.style.display = 'none';
        }

        validateDecisions(decisions) {
            // Read-only: never re-render the inputs here (that wiped the entries before v1.1).
            var inp1 = document.getElementById('var1Input');
            var inp2 = document.getElementById('var2Input');
            var inp3 = document.getElementById('var3Input');
            var sel = document.getElementById('relaxInput');
            if (inp1) decisions.var1 = parseFloat(inp1.value) || 0;
            if (inp2) decisions.var2 = parseFloat(inp2.value) || 0;
            if (inp3) decisions.var3 = parseFloat(inp3.value) || 0;
            if (sel) decisions.relax = sel.value || '';

            if (decisions.var1 < 0 || decisions.var2 < 0 || decisions.var3 < 0) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('negative_warning'), 'warning');
                return false;
            }
            if (sel && !/^c\d+$/.test(decisions.relax)) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('relax_missing'), 'warning');
                return false;
            }
            return true;
        }

        _checkConstraints(round, vals) {
            var results = [];
            for (var c = 0; c < round.constraints.length; c++) {
                var con = round.constraints[c];
                var lhs = 0;
                for (var j = 0; j < con.coeffs.length; j++) { lhs += con.coeffs[j] * (vals[j] || 0); }
                var feasible = true;
                var slack = 0;
                if (con.type === 'leq') {
                    feasible = lhs <= con.rhs + 0.001;
                    slack = con.rhs - lhs;
                } else if (con.type === 'geq') {
                    feasible = lhs >= con.rhs - 0.001;
                    slack = lhs - con.rhs;
                } else {
                    feasible = Math.abs(lhs - con.rhs) < 0.5;
                    slack = 0;
                }
                results.push({ index: c, desc: this._t(con.desc), feasible: feasible, lhs: lhs, rhs: con.rhs, type: con.type, slack: slack });
            }
            return results;
        }

        _calcObjective(round, vals) {
            var z = 0;
            for (var j = 0; j < round.objCoeffs.length; j++) { z += round.objCoeffs[j] * (vals[j] || 0); }
            return z;
        }

        // Round score (v1.2). Plan 75 percent: an optimal plan earns 100, every 1 percent of the optimum left
        // on the table costs 12 points, a feasible plan never earns less than 10, an infeasible plan earns 0.
        // Shadow-price read 25 percent: the constraint whose one-unit relaxation adds most to the objective.
        _evaluate(idx, vals, relax) {
            var round = this.ROUNDS[idx];
            var conResults = this._checkConstraints(round, vals);
            var feasible = conResults.every(function (c) { return c.feasible; });
            var obj = this._calcObjective(round, vals);
            var opt = round.optimalValue;
            var gapPct = feasible ? Math.max(0, (opt - obj) / opt * 100) : null;
            var plan = feasible ? Math.max(10, Math.round(100 - 12 * gapPct)) : 0;
            var efficiency = feasible ? Math.min(100, Math.round(obj / opt * 100)) : 0;
            var best = 0, bestIdx = [];
            for (var s = 0; s < round.shadowPrices.length; s++) { if (round.shadowPrices[s].value > best) { best = round.shadowPrices[s].value; } }
            for (var b = 0; b < round.shadowPrices.length; b++) { if (best > 0 && round.shadowPrices[b].value === best) { bestIdx.push(b); } }
            var pick = /^c\d+$/.test(String(relax || '')) ? parseInt(String(relax).slice(1), 10) : -1;
            var readOk = bestIdx.indexOf(pick) >= 0;
            var score = Math.round(0.75 * plan + 0.25 * (readOk ? 100 : 0));
            return { conResults: conResults, feasible: feasible, obj: obj, opt: opt, gapPct: gapPct, plan: plan, efficiency: efficiency,
                bestIdx: bestIdx, pick: pick, readOk: readOk, score: score, optimal: feasible && gapPct <= 0.5 };
        }

        // What went wrong in a round, read from the decisions actually submitted (never a generic line).
        _diagnose(idx, vals, relax) {
            var round = this.ROUNDS[idx];
            var ev = this._evaluate(idx, vals, relax);
            var out = [];
            var self = this;
            var nm = function (c) { return self._t(round.shadowPrices[c].name); };
            if (!ev.feasible) {
                var broken = ev.conResults.filter(function (c) { return !c.feasible; }).map(function (c) { return '«' + nm(c.index) + '»'; }).join(', ');
                out.push(ev.obj > ev.opt
                    ? this._L('Infeasible plan: it broke ' + broken + '. Its objective (' + this._num(ev.obj) + ') beats the optimum only because it breaks a constraint, so it is not a plan.',
                        'Plan no factible: violó ' + broken + '. Su objetivo (' + this._num(ev.obj) + ') supera al óptimo solo porque rompe una restricción, así que no es un plan.')
                    : this._L('Infeasible plan: it broke ' + broken + '. A plan has to meet every constraint before its objective counts.',
                        'Plan no factible: violó ' + broken + '. Un plan tiene que cumplir todas las restricciones antes de que su objetivo cuente.'));
            } else if (!ev.optimal) {
                var gapTxt = this._num(ev.gapPct);
                var named = false;
                var geq = ev.conResults.filter(function (c) { return c.type === 'geq'; });
                var atFloor = geq.length >= 2 && geq.every(function (c) { return Math.abs(c.slack) < 0.5; });
                for (var c = 0; c < ev.conResults.length; c++) {
                    var cr = ev.conResults[c], sp = round.shadowPrices[c].value, con = round.constraints[c];
                    if (sp > 0 && cr.type !== 'eq' && cr.slack >= 0.5) {
                        named = true;
                        if (con.kind === 'budget') {
                            out.push(this._L('You left budget unspent: ' + this._num(cr.slack) + ' of slack in «' + nm(c) + '», and the budget shadow price was ' + this._num(sp) + ' per unit.',
                                'Dejaste presupuesto sin usar: ' + this._num(cr.slack) + ' de holgura en «' + nm(c) + '», y el precio sombra del presupuesto era ' + this._num(sp) + ' por unidad.'));
                        } else {
                            out.push(this._L('You left slack in «' + nm(c) + '» (' + this._num(cr.slack) + '), a constraint worth ' + this._num(sp) + ' per unit at the optimum.',
                                'Dejaste holgura en «' + nm(c) + '» (' + this._num(cr.slack) + '), una restricción que vale ' + this._num(sp) + ' por unidad en el óptimo.'));
                        }
                    }
                }
                if (atFloor) {
                    named = true;
                    out.push(this._L('You stopped at the required minimums instead of using the resources left over.',
                        'Te quedaste en los mínimos exigidos en lugar de usar los recursos que sobraban.'));
                }
                if (round.activeVars >= 3) {
                    var act = vals.slice(0, round.activeVars);
                    if (Math.max.apply(null, act) - Math.min.apply(null, act) <= 2) {
                        named = true;
                        out.push(this._L('You made an equal split (the 1/N rule): splitting evenly is not optimising when the coefficients differ.',
                            'Hiciste un reparto igual (regla 1/N): repartir por igual no es optimizar cuando los coeficientes difieren.'));
                    }
                }
                out.unshift(this._L('Feasible plan, ' + gapTxt + ' % below the optimum.', 'Plan factible, ' + gapTxt + ' % por debajo del óptimo.'));
                if (!named) {
                    out.push(this._L('Your plan does not sit on the corner where the optimum lies: compare its binding constraints with the optimum.',
                        'Tu plan no está en el vértice del óptimo: compara sus restricciones vinculantes con las del óptimo.'));
                }
            }
            if (ev.pick < 0) {
                out.push(this._L('No shadow-price read was given.', 'No diste lectura del precio sombra.'));
            } else if (!ev.readOk) {
                var bestNames = ev.bestIdx.map(function (b) { return '«' + nm(b) + '»'; }).join(this._L(' or ', ' o '));
                out.push(this._L('Shadow-price read: you chose «' + nm(ev.pick) + '» (' + this._num(round.shadowPrices[ev.pick].value) + ' per unit); the most valuable was ' + bestNames + ' (' + this._num(round.shadowPrices[ev.bestIdx[0]].value) + ').',
                    'Lectura del precio sombra: elegiste «' + nm(ev.pick) + '» (' + this._num(round.shadowPrices[ev.pick].value) + ' por unidad); la que más valía era ' + bestNames + ' (' + this._num(round.shadowPrices[ev.bestIdx[0]].value) + ').'));
            }
            return { ev: ev, lines: out };
        }

        _computeRound(state) {
            var period = state.currentPeriod || 1;
            var idx = Math.min(period - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var d = state.decisions || {};
            var vals = [Number(d.var1) || 0, Number(d.var2) || 0, Number(d.var3) || 0];
            var relax = String(d.relax || '');
            var ev = this._evaluate(idx, vals, relax);
            var ds = state.domainState;
            // Write by index and re-sum: replaying a round after an undo gives the same state.
            var keys = ['scoreHistory', 'efficiencyHistory', 'objectiveHistory', 'optimalHistory', 'planHistory', 'readHistory', 'feasibleHistory', 'decisionHistory'];
            for (var k = 0; k < keys.length; k++) { ds[keys[k]] = (Array.isArray(ds[keys[k]]) ? ds[keys[k]] : []).slice(0, period - 1); }
            ds.scoreHistory[period - 1] = ev.score;
            ds.efficiencyHistory[period - 1] = ev.efficiency;
            ds.objectiveHistory[period - 1] = ev.obj;
            ds.optimalHistory[period - 1] = round.optimalValue;
            ds.planHistory[period - 1] = ev.plan;
            ds.readHistory[period - 1] = ev.readOk ? 1 : 0;
            ds.feasibleHistory[period - 1] = ev.feasible ? 1 : 0;
            ds.decisionHistory[period - 1] = { vals: vals, relax: relax };
            var sum = function (a) { return a.reduce(function (s, v) { return s + (Number(v) || 0); }, 0); };
            ds.totalScore = sum(ds.scoreHistory);
            ds.scenariosCompleted = ds.scoreHistory.length;
            var n = ds.scenariosCompleted || 1;
            var grade = Math.max(0, Math.min(100, Math.round(ds.totalScore / n)));
            ds.performance = Object.assign({}, ds.performance || {}, {
                overallScore: grade,
                outcome: Math.round(sum(ds.planHistory) / n),
                process: Math.round(sum(ds.readHistory) / n * 100)
            });
            ds.lastShown = period;

            var self = this;
            var maxP = (window.mySimulation && window.mySimulation.state && window.mySimulation.state.maxPeriods) || this.ROUNDS.length;
            setTimeout(function () {
                // Advance the briefing to the next scenario first, then show the analysis of the round just scored.
                if (period < maxP) { self._updateBriefing({ currentPeriod: period + 1 }); }
                self._showResults(idx, vals, relax);
            }, 400);
            return { period: period, idx: idx, vals: vals, relax: relax, ev: ev, grade: grade };
        }

        calculateResults(state) {
            var r = this._computeRound(state);
            return {
                period: r.period,
                scenario: this._t(this.ROUNDS[r.idx].title),
                scenarioIndex: r.idx,
                vals: r.vals,
                relax: r.relax,
                feasible: r.ev.feasible,
                optimal: r.ev.optimal,
                studentObjective: r.ev.obj,
                optimalObjective: r.ev.opt,
                efficiency: r.ev.efficiency,
                planScore: r.ev.plan,
                readCorrect: r.ev.readOk,
                score: r.ev.score,
                overallScore: r.grade,
                totalScore: state.domainState.totalScore
            };
        }

        _showResults(idx, vals, relax) {
            var rp = document.getElementById('resultsPanel');
            var rc = document.getElementById('resultsContent');
            if (!rp || !rc) return;
            var round = this.ROUNDS[idx];
            var dg = this._diagnose(idx, vals, relax);
            var ev = dg.ev;
            var L = this._L.bind(this);
            var html = '';

            if (!ev.feasible) {
                html += '<div class="optima-sim-infeasible">' + L('⚠ Solution is INFEASIBLE — one or more constraints violated', '⚠ Solución NO factible — una o más restricciones violadas') + '</div>';
            }
            html += '<div class="optima-sim-results-grid">';
            html += '<div class="optima-sim-result-item"><div class="optima-sim-label">' + L('Your Objective', 'Tu Objetivo') + '</div><div class="optima-sim-value">' + this._num(ev.obj) + '</div></div>';
            html += '<div class="optima-sim-result-item"><div class="optima-sim-label">' + L('Optimal', 'Óptimo') + '</div><div class="optima-sim-value">' + this._num(ev.opt) + '</div></div>';
            html += '<div class="optima-sim-result-item"><div class="optima-sim-label">' + L('Plan score', 'Nota del plan') + '</div><div class="optima-sim-value">' + ev.plan + '</div></div>';
            html += '<div class="optima-sim-result-item"><div class="optima-sim-label">' + L('Shadow-price read', 'Lectura del precio sombra') + '</div><div class="optima-sim-value">' + (ev.readOk ? L('✔ correct', '✔ correcta') : L('✖ not the highest', '✖ no era la mayor')) + '</div></div>';
            html += '<div class="optima-sim-result-item"><div class="optima-sim-label">' + L('Round score', 'Nota de la ronda') + '</div><div class="optima-sim-value">' + ev.score + '</div></div>';
            html += '<div class="optima-sim-result-item"><div class="optima-sim-label">' + L('Optimal Solution', 'Solución Óptima') + '</div><div class="optima-sim-value" style="font-size:1rem;">' + this._t(round.optimalDesc) + '</div></div>';
            html += '</div>';
            if (dg.lines.length) {
                html += '<ul class="optima-sim-diag">';
                for (var i = 0; i < dg.lines.length; i++) { html += '<li>' + dg.lines[i] + '</li>'; }
                html += '</ul>';
            }

            html += '<h4 style="margin-top:18px;color:#3d55b8;">' + L('Constraint Analysis', 'Análisis de Restricciones') + '</h4>';
            html += '<table class="optima-sim-shadow-table"><thead><tr><th scope="col">' + L('Constraint', 'Restricción') + '</th><th scope="col">' + L('Status', 'Estado') + '</th><th scope="col">' + L('Slack', 'Holgura') + '</th></tr></thead><tbody>';
            for (var c = 0; c < ev.conResults.length; c++) {
                var cr = ev.conResults[c];
                var statusClass = 'optima-sim-nonbinding', statusText;
                if (!cr.feasible) { statusClass = 'optima-sim-binding'; statusText = L('✖ Violated', '✖ Violada'); }
                else if (Math.abs(cr.slack) < 0.5) { statusClass = 'optima-sim-binding'; statusText = L('● Binding', '● Vinculante'); }
                else { statusText = L('○ Non-binding', '○ No vinculante'); }
                html += '<tr><td>' + cr.desc + '</td><td class="' + statusClass + '">' + statusText + '</td><td>' + this._num(cr.slack) + '</td></tr>';
            }
            html += '</tbody></table>';

            html += '<h4 style="margin-top:18px;color:#7a3a99;">' + L('Shadow Prices (Dual Values)', 'Precios Sombra (Valores Duales)') + '</h4>';
            html += '<table class="optima-sim-shadow-table"><thead><tr><th scope="col">' + L('Constraint', 'Restricción') + '</th><th scope="col">' + L('Shadow Price', 'Precio Sombra') + '</th><th scope="col">' + L('Interpretation', 'Interpretación') + '</th></tr></thead><tbody>';
            for (var s = 0; s < round.shadowPrices.length; s++) {
                var sp = round.shadowPrices[s];
                html += '<tr><td><strong>' + this._t(sp.name) + '</strong></td><td>' + this._num(sp.value) + '</td><td>' + this._t(sp.explanation) + '</td></tr>';
            }
            html += '</tbody></table>';
            html += '<div class="optima-sim-insight-box"><strong>' + L('💡 Key Insight:', '💡 Idea clave:') + '</strong> ' + this._t(round.insight) + '</div>';

            rc.innerHTML = html;
            rp.style.display = 'block';
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('scoreDisplay', 'domainState.totalScore', function(v) { return Math.round(v || 0); });
            uiManager.bind('avgDisplay', 'domainState.scenariosCompleted', function(v) {
                if (!window.mySimulation || !window.mySimulation.state) return '0';
                var ds = window.mySimulation.state.domainState;
                if (!ds || !ds.scenariosCompleted) return '0';
                return String(Math.round(ds.totalScore / ds.scenariosCompleted));
            });
            uiManager.bind('roundScoreDisplay', 'results.score', function(v) { return v !== undefined ? String(v) : '--'; });
            uiManager.bind('objValueDisplay', 'results.studentObjective', function(v) {
                return v !== undefined ? Number(v).toLocaleString() : '--';
            });
        }

        getChartConfig() {
            var es = this._lang() === 'es';
            return {
                scoreChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: es ? 'Nota de la ronda' : 'Round score',
                                data: [],
                                backgroundColor: 'rgba(61,85,184,0.75)',
                                borderColor: '#3d55b8',
                                borderWidth: 2,
                                borderRadius: 6
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: es ? 'Nota por escenario (0-100)' : 'Score by scenario (0-100)' }
                        },
                        scales: {
                            y: { beginAtZero: true, max: 100 }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var ds = (state && state.domainState) || {};
            var hist = ds.scoreHistory || [];
            var labels = hist.map(function(_, i) { return 'S' + (i + 1); });
            return {
                scoreChart: {
                    labels: labels,
                    datasets: [{ data: hist }]
                }
            };
        }

        _tierOf(avg, feasibleCount, n) {
            var id = 'novice';
            if (avg >= 60 && feasibleCount >= 3) id = 'practitioner';
            if (avg >= 80 && feasibleCount >= 4) id = 'proficient';
            if (avg >= 95 && feasibleCount === n) id = 'expert';
            return id;
        }

        getPerformanceSummary(history) {
            var t = (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };
            if (!history || !history.length) return {};
            var self = this;
            var rows = history.map(function(r, i) {
                var res = r.results || {};
                var idx = res.scenarioIndex != null ? res.scenarioIndex : Math.min(i, self.ROUNDS.length - 1);
                var vals = res.vals || [0, 0, 0];
                var dg = self._diagnose(idx, vals, res.relax);
                return { idx: idx, score: dg.ev.score, plan: dg.ev.plan, read: dg.ev.readOk, feasible: dg.ev.feasible, optimal: dg.ev.optimal, lines: dg.lines };
            });
            var n = rows.length;
            var total = rows.reduce(function(s, r) { return s + r.score; }, 0);
            var avg = total / n;
            var grade = Math.max(0, Math.min(100, Math.round(avg)));
            var feasibleCount = rows.filter(function(r) { return r.feasible; }).length;
            var optimalCount = rows.filter(function(r) { return r.optimal; }).length;
            var readCount = rows.filter(function(r) { return r.read; }).length;
            var outcome = Math.round(rows.reduce(function(s, r) { return s + r.plan; }, 0) / n);
            var tier = this._tierOf(avg, feasibleCount, n);

            // Turning point: the lowest-scoring round (the first one on a tie).
            var tp = null;
            rows.forEach(function(r) { if (r.score < 100 && (!tp || r.score < tp.score)) { tp = r; } });
            var L = this._L.bind(this);
            var turning = tp
                ? L('Scenario ' + (tp.idx + 1) + ' (' + this._t(this.ROUNDS[tp.idx].title).replace(/^[^:]*:\s*/, '') + ', score ' + tp.score + '): ', 'Escenario ' + (tp.idx + 1) + ' (' + this._t(this.ROUNDS[tp.idx].title).replace(/^[^:]*:\s*/, '') + ', nota ' + tp.score + '): ') + (tp.lines[0] || '')
                : L('None: every plan was optimal and every shadow-price read was right.', 'Ninguno: todos los planes fueron óptimos y todas las lecturas del precio sombra, correctas.');

            var insights = [];
            rows.forEach(function(r) {
                if (r.lines.length && insights.length < 5) {
                    insights.push(L('Scenario ', 'Escenario ') + (r.idx + 1) + ': ' + r.lines.join(' '));
                }
            });
            if (!insights.length) {
                insights.push(L('Five optimal plans: you found the corner of each feasible region and named the constraint worth relaxing first.',
                    'Cinco planes óptimos: encontraste el vértice de cada región factible y nombraste la restricción que conviene relajar primero.'));
            }
            if (insights.length < 3 && optimalCount === n) {
                insights.push(L('Next step: say how far each shadow price holds (its allowable range) before you buy capacity at that price.',
                    'Siguiente paso: indica hasta dónde vale cada precio sombra (su rango permitido) antes de comprar capacidad a ese precio.'));
            }

            return {
                totalScore: total,
                composite: grade,
                overallScore: grade,
                score: grade,
                averageEfficiency: grade,
                outcomeScore: outcome,
                processReads: readCount,
                optimalPlans: optimalCount,
                feasibleSolutions: feasibleCount,
                totalScenarios: n,
                performance: tier,
                performanceKey: 'tier_' + tier,
                performanceLabel: t('tier_' + tier),
                turningPoint: turning,
                insights: insights,
                questions: [t('q1'), t('q2'), t('q3')]
            };
        }

        formatCompletionMessage(summary) {
            var t = (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };
            if (!summary || summary.totalScenarios == null) return '';
            var esc = function(s) { return String(s == null ? '' : s); };
            var li = function(arr) { return (arr || []).map(function(i) { return '<li style="margin-bottom:6px;">' + esc(i) + '</li>'; }).join(''); };
            var n = summary.totalScenarios;
            return '<div class="optima-sim-cm" style="padding:10px;">' +
                '<div style="text-align:center;">' +
                '<div style="font-size:0.8rem;text-transform:uppercase;letter-spacing:1px;color:#555;">' + t('final_score_label') + '</div>' +
                '<div style="font-size:3rem;font-weight:700;color:#3d55b8;line-height:1.1;">' + summary.overallScore + '<span style="font-size:1.2rem;color:#555;">/100</span></div>' +
                '<div style="font-size:1.15rem;font-weight:600;color:#1e7e45;margin-bottom:10px;">' + esc(summary.performanceLabel) + '</div>' +
                '<div style="color:#333;margin-bottom:6px;">' + t('outcome_label') + ': <strong>' + summary.outcomeScore + '/100</strong> · ' + t('process_label') + ': <strong>' + summary.processReads + '/' + n + '</strong></div>' +
                '<div style="color:#333;margin-bottom:14px;">' + t('optimal_label') + ': <strong>' + summary.optimalPlans + '/' + n + '</strong> · ' + t('feasible_label') + ': <strong>' + summary.feasibleSolutions + '/' + n + '</strong></div>' +
                '</div>' +
                '<div style="max-width:560px;margin:0 auto;text-align:left;">' +
                '<h5 style="margin-bottom:6px;">' + t('turning_label') + '</h5><p style="margin:0 0 12px;">' + esc(summary.turningPoint) + '</p>' +
                '<h5 style="margin-bottom:6px;">' + t('takeaways_label') + '</h5><ul style="padding-left:20px;margin:0 0 12px;">' + li(summary.insights) + '</ul>' +
                '<h5 style="margin-bottom:6px;">' + t('questions_label') + '</h5><ol style="padding-left:20px;margin:0;">' + li(summary.questions) + '</ol>' +
                '</div></div>';
        }

        getHint(state, results) {
            if (!results) return null;
            if (!results.feasible) { return window.mySimulation.t('hint_infeasible'); }
            if (results.planScore != null && results.planScore < 50) { return window.mySimulation.t('hint_low_efficiency'); }
            if (results.planScore != null && results.planScore < 100) { return window.mySimulation.t('hint_mid_efficiency'); }
            if (results.planScore === 100 && results.readCorrect) { return window.mySimulation.t('hint_excellent'); }
            return null;
        }

